// Ordered most-recently-touched first rather than by priority: 0 means "no priority", so
// the numeric order puts unprioritised work at the top, and the display order is a client
// concern the replica already implements. This only has to be stable and useful.
func (q *Queries) ListMyIssues(ctx context.Context, arg ListMyIssuesParams) ([]Issue, error) {
	rows, err := q.db.Query(ctx, listMyIssues,
		arg.WorkspaceID,
		arg.AssigneeID,
		arg.TeamIds,
		arg.IncludeCompleted,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Issue{}
	for rows.Next() {
		var i Issue
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.TeamID,
			&i.Number,
			&i.Title,
			&i.Description,
			&i.StateID,
			&i.AssigneeID,
			&i.CreatorID,
			&i.Priority,
			&i.SortOrder,
			&i.StartedAt,
			&i.CompletedAt,
			&i.CanceledAt,
			&i.ArchivedAt,
			&i.DeletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Estimate,
			&i.DueDate,
			&i.DueDateSource,
			&i.ParentID,
			&i.SubIssueSortOrder,
			&i.TemplateID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const restoreIssue = `-- name: RestoreIssue :one
UPDATE issue SET deleted_at = NULL
WHERE id = $1 AND deleted_at IS NOT NULL AND deleted_at > $2
RETURNING id, workspace_id, team_id, number, title, description, state_id,
          assignee_id, creator_id, priority, sort_order,
          started_at, completed_at, canceled_at,
          archived_at, deleted_at, created_at, updated_at,
          estimate, due_date, due_date_source, parent_id, sub_issue_sort_order, template_id
`

type RestoreIssueParams struct {
	ID           uuid.UUID
	DeletedAfter *time.Time
}

// RestoreIssue returns the row because a restore puts the issue back on the sync stream,
// and the payload has to be the issue as it is now — not as the client last saw it before
// the delete.
//
// The window is a parameter rather than a literal: how long a delete stays undoable is a
// product decision, and burying "30 days" in a query means changing it is a migration.
func (q *Queries) RestoreIssue(ctx context.Context, arg RestoreIssueParams) (Issue, error) {
	row := q.db.QueryRow(ctx, restoreIssue, arg.ID, arg.DeletedAfter)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TeamID,
		&i.Number,
		&i.Title,
		&i.Description,
		&i.StateID,
		&i.AssigneeID,
		&i.CreatorID,
		&i.Priority,
		&i.SortOrder,
		&i.StartedAt,
		&i.CompletedAt,
		&i.CanceledAt,
		&i.ArchivedAt,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Estimate,
		&i.DueDate,
		&i.DueDateSource,
		&i.ParentID,
		&i.SubIssueSortOrder,
		&i.TemplateID,
	)
	return i, err
}

const softDeleteIssue = `-- name: SoftDeleteIssue :exec
UPDATE issue SET deleted_at = now() WHERE id = $1 AND deleted_at IS NULL
`

func (q *Queries) SoftDeleteIssue(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, softDeleteIssue, id)
	return err
}

const streamIssuesForBootstrap = `-- name: StreamIssuesForBootstrap :many
SELECT id, workspace_id, team_id, number, title, description, state_id,
       assignee_id, creator_id, priority, sort_order,
       started_at, completed_at, canceled_at,
       archived_at, deleted_at, created_at, updated_at,
       estimate, due_date, due_date_source, parent_id, sub_issue_sort_order, template_id
FROM issue
WHERE workspace_id = $1
  AND team_id = ANY($2::uuid[])
  AND archived_at IS NULL
  AND deleted_at IS NULL
  AND id > $3
ORDER BY id
LIMIT $4
`

type StreamIssuesForBootstrapParams struct {
	WorkspaceID uuid.UUID
	TeamIds     []uuid.UUID
	AfterID     uuid.UUID
	PageSize    int32
}

// StreamIssuesForBootstrap feeds the initial snapshot. Ordered by id (UUIDv7, so
// effectively creation order) and keyset-paginated: OFFSET would degrade quadratically
// on a workspace with a hundred thousand issues, which is exactly where it matters.
func (q *Queries) StreamIssuesForBootstrap(ctx context.Context, arg StreamIssuesForBootstrapParams) ([]Issue, error) {
	rows, err := q.db.Query(ctx, streamIssuesForBootstrap,
		arg.WorkspaceID,
		arg.TeamIds,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Issue{}
	for rows.Next() {
		var i Issue
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.TeamID,
			&i.Number,
			&i.Title,
			&i.Description,
			&i.StateID,
			&i.AssigneeID,
			&i.CreatorID,
			&i.Priority,
			&i.SortOrder,
			&i.StartedAt,
			&i.CompletedAt,
			&i.CanceledAt,
			&i.ArchivedAt,
			&i.DeletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Estimate,
			&i.DueDate,
			&i.DueDateSource,
			&i.ParentID,
			&i.SubIssueSortOrder,
			&i.TemplateID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

