const updateIssue = `-- name: UpdateIssue :one
UPDATE issue
SET title            = COALESCE($1, title),
    description      = COALESCE($2, description),
    state_id         = COALESCE($3, state_id),
    priority         = COALESCE($4, priority),
    sort_order       = COALESCE($5, sort_order),
    team_id          = COALESCE($6, team_id),
    number           = COALESCE($7, number),
    due_date_source  = COALESCE($8, due_date_source),
    sub_issue_sort_order = COALESCE($9, sub_issue_sort_order),
    -- Assignee is three-state: absent (leave alone), set, or explicitly cleared. A plain
    -- COALESCE cannot express "clear", so the caller passes clear_assignee separately.
    assignee_id  = CASE WHEN $10::boolean THEN NULL
                        ELSE COALESCE($11, assignee_id) END,
    -- The same three states, for the same reason. Unestimated is not zero, no due date is
    -- not the epoch, and no parent is not a sub-issue of nothing — each needs a way to say
    -- "remove it" that a nil pointer cannot express.
    estimate     = CASE WHEN $12::boolean THEN NULL
                        ELSE COALESCE($13, estimate) END,
    due_date     = CASE WHEN $14::boolean THEN NULL
                        ELSE COALESCE($15, due_date) END,
    -- Clearing the parent leaves sub_issue_sort_order behind rather than nulling it: if
    -- the issue is re-parented to the same issue by an undo, it lands back where it was.
    parent_id    = CASE WHEN $16::boolean THEN NULL
                        ELSE COALESCE($17, parent_id) END,
    -- Category timestamps are set by the domain layer, which knows the transition rules
    -- (started_at is never cleared once set, because insights read it).
    started_at   = CASE WHEN $18::boolean THEN $19   ELSE started_at   END,
    completed_at = CASE WHEN $18::boolean THEN $20 ELSE completed_at END,
    canceled_at  = CASE WHEN $18::boolean THEN $21  ELSE canceled_at  END
WHERE id = $22 AND deleted_at IS NULL
RETURNING id, workspace_id, team_id, number, title, description, state_id,
          assignee_id, creator_id, priority, sort_order,
          started_at, completed_at, canceled_at,
          archived_at, deleted_at, created_at, updated_at,
          estimate, due_date, due_date_source, parent_id, sub_issue_sort_order, template_id
`

type UpdateIssueParams struct {
	Title             *string
	Description       *string
	StateID           *uuid.UUID
	Priority          *int16
	SortOrder         *string
	TeamID            *uuid.UUID
	Number            *int64
	DueDateSource     *string
	SubIssueSortOrder *string
	ClearAssignee     bool
	AssigneeID        *uuid.UUID
	ClearEstimate     bool
	Estimate          *int16
	ClearDueDate      bool
	DueDate           pgtype.Date
	ClearParent       bool
	ParentID          *uuid.UUID
	SetTimestamps     bool
	StartedAt         *time.Time
	CompletedAt       *time.Time
	CanceledAt        *time.Time
	ID                uuid.UUID
}

func (q *Queries) UpdateIssue(ctx context.Context, arg UpdateIssueParams) (Issue, error) {
	row := q.db.QueryRow(ctx, updateIssue,
		arg.Title,
		arg.Description,
		arg.StateID,
		arg.Priority,
		arg.SortOrder,
		arg.TeamID,
		arg.Number,
		arg.DueDateSource,
		arg.SubIssueSortOrder,
		arg.ClearAssignee,
		arg.AssigneeID,
		arg.ClearEstimate,
		arg.Estimate,
		arg.ClearDueDate,
		arg.DueDate,
		arg.ClearParent,
		arg.ParentID,
		arg.SetTimestamps,
		arg.StartedAt,
		arg.CompletedAt,
		arg.CanceledAt,
		arg.ID,
	)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TeamID,
		&i.Number,
		&i.Title,
		&i.Description,
		&i.StateID,
		&i.AssigneeID,
		&i.CreatorID,
		&i.Priority,
		&i.SortOrder,
		&i.StartedAt,
		&i.CompletedAt,
		&i.CanceledAt,
		&i.ArchivedAt,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Estimate,
		&i.DueDate,
		&i.DueDateSource,
		&i.ParentID,
		&i.SubIssueSortOrder,
		&i.TemplateID,
	)
	return i, err
}
